package com.shopsphere.rmi.server;import com.shopsphere.rmi.remote.InventoryService;import java.rmi.*;import java.rmi.server.*;import java.util.*;public class InventoryServiceImpl extends UnicastRemoteObject implements InventoryService{Map<Integer,Integer> stock=new HashMap<>();public InventoryServiceImpl()throws RemoteException{stock.put(1,25);stock.put(2,18);}public String getProduct(int id){return id==1?"Wireless Headphones":id==2?"Smart Watch":"Unknown";}public int getStock(int id){return stock.getOrDefault(id,0);}public boolean updateStock(int id,int q){if(q<0||q>getStock(id))return false;stock.put(id,getStock(id)-q);return true;}}
